cypress_script:
describe('JavaScript Alert Dialogs', () => {
  it('should display and dismiss JS Alert', () => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
    cy.contains('button', 'Click for JS Alert').click();
    cy.on('window:alert', (text) => {
      expect(text).to.eq('I am a JS Alert');
    });
  });

  it('should display JS Prompt and show result', () => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
    cy.contains('button', 'Click for JS Prompt').click();
    cy.window().then((win) => {
      cy.stub(win, 'prompt').returns('Test input');
    });
    cy.on('window:alert', (text) => {
      expect(text).to.eq('I am a JS Prompt');
    });
    cy.get('#result').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('JavaScript Alert Dialogs', () => {
  test('should display and dismiss JS Alert', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
    page.on('dialog', async dialog => {
      expect(dialog.message()).toBe('I am a JS Alert');
      await dialog.dismiss();
    });
    await page.click('text=Click for JS Alert');
  });

  test('should display JS Prompt and show result', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
    page.on('dialog', async dialog => {
      expect(dialog.message()).toBe('I am a JS Prompt');
      await dialog.accept('Test input');
    });
    await page.click('text=Click for JS Prompt');
    const resultText = await page.textContent('#result');
    expect(resultText).toBe('You entered: Test input');
  });
});
